rm -f lib/.gitkeep tests/.gitkeep && mkdir -p probes && cat > lib/observe.mlpl <<'EOF'
# Smallest observation facade over emit_frame: named, stepped, identity-returning checkpoints.

def u:observe(name, step, value) {
  "Record value under a stable slash-separated name at an integer step and return it unchanged.";
  emit_frame(name, step, value)
}

def u:metric(name, step, value) {
  "Record a scalar measurement (loss, accuracy, bytes, milliseconds) and return it unchanged.";
  emit_frame(name, step, value)
}

def u:observe_path(prefix, leaf) {
  "Join a mechanism prefix and a leaf into one stable observation name.";
  prefix + "/" + leaf
}
EOF
cat > tests/test_observe.mlpl <<'EOF'
# Observation facade contract: identity return and stable naming.
include "lib/observe.mlpl";

@test {name: "observe returns the value unchanged for scalar and rank-two input", tags: ["observe", "facade"]}
def u:test_observe_identity() {
  "The facade must never alter the observed value.";
  u:assert_eq(u:observe("probe/scalar", 0, 7), 7, "scalar identity")?;
  u:assert_eq(u:observe("probe/matrix", 1, [[1, 2], [3, 4]]), [[1, 2], [3, 4]], "matrix identity")
}

@test {name: "metric returns the scalar unchanged", tags: ["observe", "facade"]}
def u:test_metric_identity() {
  "A metric is a scalar observation.";
  u:assert_eq(u:metric("probe/loss", 3, 0.25), 0.25, "metric identity")
}

@test {name: "observe_path joins prefix and leaf with one slash", tags: ["observe", "naming"]}
def u:test_observe_path() {
  "Names group by mechanism prefix in a generic host.";
  u:assert_text_eq(u:observe_path("moe/router", "logits"), "moe/router/logits", "joined name")
}

u:run_registered_tests()
EOF
cat > tests/test_capability_probes.mlpl <<'EOF'
# Executable capability probes behind docs/sw-mlpl-blockers.md and docs/sw-mlpl-findings.md.

def u:mse(a, b) {
  "Mean squared error between two same-shaped arrays.";
  mean((a - b) * (a - b))
}

def u:two_expert_moe(x, mask, router, e0, e1) {
  "Switch-style top-1 mixture: softmax router probability times a constant selection mask.";
  g = softmax(matmul(x, router)) * mask;
  reshape(take(g, 1, 0), [6, 1]) * apply(e0, x) + reshape(take(g, 1, 1), [6, 1]) * apply(e1, x)
}

def u:recur3(block, x0) {
  "One shared block applied three times by nested apply; the tape accumulates its gradient.";
  apply(block, apply(block, apply(block, x0)))
}

def u:kl(p, q) {
  "Kullback-Leibler divergence KL(p || q) composed from log and reduce_add.";
  reduce_add(p * (log(p) - log(q)))
}

@test {name: "softmax takes one argument in eager and tape evaluation (F1 resolved)", tags: ["probe", "supported"]}
def u:test_softmax_arity() {
  "One softmax spelling must evaluate and differentiate.";
  W = param[2, 3];
  W = [[1, 2, 3], [3, 2, 1]];
  eager = softmax(W);
  u:assert_approx(reduce_add(take(eager, 0, 0)), 1, 0.000001, "eager rows sum to one")?;
  u:assert_eq(eager, softmax(W, 1), "one-argument form equals last-axis form")?;
  g = grad(reduce_add(softmax(W) * [[1, 0, 0], [0, 1, 0]]), W);
  u:assert_shape(g, [2, 3], "tape softmax gradient shape")
}

@test {name: "adam trains a list of expert models plus a router param through a user function (F2 resolved)", tags: ["probe", "supported", "moe"]}
def u:test_adam_mixed_list_user_function() {
  "Dense-masked MoE written as reusable source must train every part.";
  d = 4;
  h = randn(1, [6, d]);
  target = randn(2, [6, d]);
  e0 = chain(linear(d, 8, 10), relu_layer(), linear(8, d, 11));
  e1 = chain(linear(d, 8, 12), relu_layer(), linear(8, d, 13));
  Wr = param[4, 2];
  Wr = randn(3, [4, 2]) * 0.5;
  Wr0 = Wr;
  mask = one_hot(argmax(matmul(h, Wr), 1), 2);
  before = u:mse(u:two_expert_moe(h, mask, Wr, e0, e1), target);
  train 20 {
    adam(u:mse(u:two_expert_moe(h, mask, Wr, e0, e1), target), [e0, e1, Wr], 0.05, 0.9, 0.999, 0.00000001);
    0
  };
  after = u:mse(u:two_expert_moe(h, mask, Wr, e0, e1), target);
  u:assert_lt(after, before * 0.5, "loss at least halves")?;
  u:assert_gt(reduce_add(abs(Wr - Wr0)), 0.1, "router parameter moved")
}

@test {name: "one shared block applied R times trains through nested apply (F3 documented)", tags: ["probe", "supported", "recurrence"]}
def u:test_shared_block_recurrence() {
  "Weight sharing is spelled by reusing one block, not by chain.";
  d = 4;
  x = randn(1, [5, d]);
  target = randn(2, [5, d]);
  block = residual(chain(rms_norm(d), linear(d, d, 7)));
  u:assert_eq(param_count(chain(block, block, block)), 3 * param_count(block), "chain copies, it does not share")?;
  before = u:mse(u:recur3(block, x), target);
  train 15 { adam(u:mse(u:recur3(block, x), target), block, 0.05, 0.9, 0.999, 0.00000001); 0 };
  u:assert_lt(u:mse(u:recur3(block, x), target), before * 0.5, "recurrent loss at least halves")
}

@test {name: "gather_rows scatter-adds gradient into addressed rows only (F4 resolved)", tags: ["probe", "supported", "engram"]}
def u:test_gather_rows_backward() {
  "A from-scratch addressing table must be trainable.";
  M = param[3, 2];
  M = [[1, 2], [3, 4], [5, 6]];
  u:assert_eq(grad(reduce_add(gather_rows(M, [0, 0, 2])), M), [[2, 2], [0, 0], [1, 1]], "duplicates accumulate, unaddressed rows stay zero")
}

@test {name: "KL divergence is a composition of shipped builtins, eager and on the tape (F4 documented)", tags: ["probe", "supported", "distillation"]}
def u:test_kl_composition() {
  "No kl_divergence builtin exists; the composition is the pragmatic spelling.";
  p = softmax([1, 2, 3]);
  q = softmax([1.5, 1.5, 3]);
  u:assert_gt(u:kl(p, q), 0, "KL of distinct distributions is positive")?;
  u:assert_approx(u:kl(p, p), 0, 0.000000001, "KL of identical distributions is zero")?;
  L = param[3];
  L = [1.5, 1.5, 3];
  u:assert_shape(grad(u:kl(p, softmax(L)), L), [3], "KL differentiates through softmax logits")
}

@test {name: "Engram builtins address, gather, gate, and report stats (supported)", tags: ["probe", "supported", "engram"]}
def u:test_engram_builtins() {
  "The pragmatic Engram is a builtin call; the from-scratch lesson checks parity against it.";
