  ratios = [full.ratios.arithmetic, full.ratios.sequence, full.ratios.mlpl, full.ratios.prose];
  page = str_concat(page, u:svg_text(570, 97, "k", "mixture-v0.json ratios for 120 examples"));
  j = 0;
  while lt(j, 4) {
    page = str_concat(page, u:svg_rect(570, 110 + j * 40, round(ratios * 800), 24, u:tag_class(j)));
    page = str_concat(page, u:svg_text(578, 127 + j * 40, "", str_concat(str_concat(str_concat(unwrap(list_get(names, j)), " "), u:svg_num(take(ratios, 0, j) * 100)), str_concat(str_concat("% = ", u:svg_num(take(counts, 0, j))), " examples"))));
    j = j + 1
  };
  page = str_concat(page, u:svg_rect(30, 340, 900, 180, "panel"));
  page = str_concat(page, u:svg_text(50, 370, "", "WHY: expert specialization is only observable if examples carry a family label; per-family exact-match accuracy is the quality metric."));
  page = str_concat(page, u:svg_text(50, 395, "", "WHY: the ratios are a fixture, not a hidden constant; prose is smallest so the exactly scored families dominate the table."));
  page = str_concat(page, u:svg_text(50, 425, "", "HOW: u:domain_counts rounds ratio * total per family and the last family absorbs rounding; u:domain_build generates"));
