cat > lib/dense.mlpl <<'EOF'
# Dense-lesson helpers: chunked flattening, masked next-token loss, greedy decoding, and prompt evaluation.
include "domain.mlpl";
include "evaluate.mlpl";

def u:rows(M, start, count) {
  "Contiguous row slice of a rank-two matrix.";
  gather_rows(M, start + range(count))
}

def u:flat_chunk(M, chunk, size) {
  "Rows chunk*size .. chunk*size+size of M flattened into one rank-one sequence.";
  reshape(u:rows(M, chunk * size, size), [size * reduce_mul(shape(take(M, 0, 0)))])
}

def u:positions(length, width) {
  "Unlabeled sinusoidal position table (labels are stripped: finding F10).";
  reshape(sinusoidal_encoding(length, width), [length, width])
}

def u:masked_ce(logits, targets, mask) {
  "Mean negative log-likelihood over masked positions only; equals cross_entropy when the mask is all ones.";
  picked = reduce_add(one_hot(targets, reduce_mul(shape(take(logits, 0, 0)))) * log(softmax(logits)), 1);
  0 - reduce_add(picked * mask) / reduce_add(mask)
}

def u:stop_id() {
  "Token id of the stop character.";
  str_find(u:domain_alphabet(), ".")
}

def u:greedy(forward, prompt_ids, max_new) {
  "Greedy decode with a forward-function reference until the stop id or max_new tokens; returns new ids only.";
  seq = prompt_ids;
  out = fill([0], 0);
  k = 0;
  while lt(k, max_new) {
    nxt = argmax(last_row(call(forward, seq)));
    seq = concat(seq, nxt);
    out = concat(out, nxt);
    k = if eq(nxt, u:stop_id()) { max_new } else { k + 1 }
  };
  out
}

def u:answer_text(ids) {
  "Decode generated ids and drop the trailing stop character if present.";
  text = u:domain_decode(ids);
  n = str_len(text);
  if n { if str_eq(str_slice(text, n - 1, 1), ".") { str_slice(text, 0, n - 1) } else { text } } else { text }
}

def u:predict_prompts(forward, prompts, index, max_new) {
  "Greedy answers for the prompts at the given row indices, as a string list.";
  n = reduce_mul(shape(index));
  acc = "";
  i = 0;
  while lt(i, n) {
    prompt = str_concat(unwrap(list_get(prompts, take(index, 0, i))), "|");
    text = u:answer_text(u:greedy(forward, unwrap(u:domain_encode(prompt)), max_new));
    acc = if eq(i, 0) { text } else { str_concat(str_concat(acc, ";"), text) };
    i = i + 1
  };
  str_split(acc, ";")
}

def u:select_list(items, index) {
  "The strings at the given indices, as a string list.";
  n = reduce_mul(shape(index));
  acc = "";
  i = 0;
  while lt(i, n) {
    item = unwrap(list_get(items, take(index, 0, i)));
    acc = if eq(i, 0) { item } else { str_concat(str_concat(acc, ";"), item) };
    i = i + 1
  };
  str_split(acc, ";")
}

def u:evaluate_prompts(forward, d, index, max_new) {
  "Per-family and overall exact-match accuracy of greedy answers over the indexed examples.";
  preds = u:predict_prompts(forward, d.prompts, index, max_new);
  answers = u:select_list(d.answers, index);
  hits = u:exact_match(preds, answers);
  tags = reshape(gather_rows(reshape(d.tags, [d.count, 1]), index), [reduce_mul(shape(index))]);
  {accuracy: u:accuracy_by_tag(hits, tags), hits: hits, preds: preds}
}
EOF
cat > tests/test_dense.mlpl <<'EOF'
# Dense-lesson helper contract: chunks, masked loss, greedy decoding, and prompt evaluation.
include "lib/dense.mlpl";

stub_logits = fill([1, 52], 0);

def u:stub_forward(seq) {
  "A forward stub whose next token is always the stop id; logits shape [len, V].";
  n = reduce_mul(shape(seq));
  base = fill([n, 52], 0);
  base + reshape(one_hot([u:stop_id()], 52), [1, 52]) * 5
}

def u:echo_forward(seq) {
  "A forward stub that predicts the id 4 (character 2) then stop.";
  n = reduce_mul(shape(seq));
  last = take(seq, 0, n - 1);
  nxt = if eq(last, u:stop_id()) { u:stop_id() } else { if eq(last, 4) { u:stop_id() } else { 4 } };
  fill([n, 52], 0) + reshape(one_hot([nxt], 52), [1, 52]) * 5
}

@test {name: "flat_chunk flattens contiguous rows into one sequence", tags: ["dense", "chunk"]}
def u:test_flat_chunk() {
  "Chunk 1 of size 2 over a 4x3 matrix is rows 2 and 3 end to end.";
  M = reshape(range(12), [4, 3]);
  u:assert_eq(u:flat_chunk(M, 1, 2), [6, 7, 8, 9, 10, 11], "second chunk")?;
  u:assert_shape(u:positions(6, 4), [6, 4], "unlabeled positions")?;
  u:assert_text_eq(labels(u:positions(6, 4)), ",", "labels stripped")
}

@test {name: "masked cross-entropy equals cross_entropy under an all-ones mask", tags: ["dense", "loss"]}
def u:test_masked_ce() {
  "Masking to the answer positions changes the mean, not the per-position terms.";
  logits = randn(1, [6, 52]);
  y = rand_ints(6, 0, 52, 2);
  u:assert_approx(u:masked_ce(logits, y, fill([6], 1)), cross_entropy(logits, y), 0.000000001, "all-ones mask")?;
  partial = u:masked_ce(logits, y, [0, 0, 0, 1, 1, 1]);
  tail = cross_entropy(u:rows(logits, 3, 3), u:rows(reshape(y, [6, 1]), 3, 3));
  u:assert_approx(partial, tail, 0.000000001, "mask selects the last three positions")
}

@test {name: "greedy decoding stops at the stop id and strips it from the answer", tags: ["dense", "decode"]}
def u:test_greedy() {
  "The stub predicts 2 then stop; the answer text is 2.";
  ids = u:greedy(:u:echo_forward, unwrap(u:domain_encode("1+1=|")), 6);
  u:assert_eq(ids, [4, u:stop_id()], "two generated ids")?;
  u:assert_text_eq(u:answer_text(ids), "2", "stop stripped")?;
  u:assert_eq(u:greedy(:u:stub_forward, [4], 3), [u:stop_id()], "immediate stop")
}

@test {name: "evaluate_prompts scores greedy answers per family", tags: ["dense", "evaluate"]}
def u:test_evaluate_prompts() {
  "A stub that always answers 2 is right only on prompts whose answer is 2.";
  d = {prompts: ["1+1=", "3+4=", "rev 2="], answers: ["2", "7", "2"], tags: [0, 0, 1], count: 3};
  r = u:evaluate_prompts(:u:echo_forward, d, [0, 1, 2], 4);
  u:assert_eq(r.hits, [1, 0, 1], "hits")?;
  u:assert_approx(r.accuracy.arithmetic, 0.5, 0.000001, "arithmetic")?;
  u:assert_eq(r.accuracy.sequence, 1, "sequence")
}

u:run_registered_tests()
EOF
