  h1 = h0 + apply(att, h0);
  h2 = h1 + apply(ffn, h1);
  apply(head, apply(norm, h2))
}
def u:forward(x1) {
  "Single sequence forward with positions 0..n-1.";
  n = reduce_mul(shape(x1));
  u:body(apply(emb, x1) + u:positions(n, dm))
}
